    /// <param name="Description">The template the tooltip fills in, <c>untranslatedBaseDescription</c>.</param>
    /// <param name="Discovery">The paragraph shown when the hero picks the artifact up, or <c>null</c>.</param>
    internal readonly record struct Row(string Name, string Description, string? Discovery);

    /// <summary>The rows, indexed by artifact id.</summary>
    internal static readonly Row[] Rows =
    [
        new("Invalid Artifact", "Invalid Artifact", null),
        new("Ultimate Book of Knowledge", "The %{name} increases the hero's knowledge by %{count}.", null),
        new("Ultimate Sword of Dominion", "The %{name} increases the hero's attack skill by %{count}.", null),
        new("Ultimate Cloak of Protection", "The %{name} increases the hero's defense skill by %{count}.", null),
        new("Ultimate Wand of Magic", "The %{name} increases the hero's spell power by %{count}.", null),
        new("Ultimate Shield", "The %{name} increases the hero's attack and defense skills by %{count} each.", null),
        new("Ultimate Staff", "The %{name} increases the hero's spell power and knowledge by %{count} each.", null),
        new("Ultimate Crown", "The %{name} increases each of the hero's basic skills by %{count} points.", null),
        new("Golden Goose", "The %{name} brings in an income of %{count} gold per day.", null),
        new("Arcane Necklace of Magic", "The %{name} increases the hero's spell power by %{count}.", "After rescuing a Sorceress from a cursed tomb, she rewards your heroism with an exquisite jeweled necklace."),
        new("Caster's Bracelet of Magic", "The %{name} increases the hero's spell power by %{count}.", "While searching through the rubble of a caved-in mine, you free a group of trapped Dwarves. Grateful, the leader gives you a golden bracelet."),
        new("Mage's Ring of Power", "The %{name} increases the hero's spell power by %{count}.", "A cry of pain leads you to a Centaur, caught in a trap. Upon setting the creature free, he hands you a small pouch. Emptying the contents, you find a dazzling jeweled ring."),
        new("Witch's Broach of Magic", "The %{name} increases the hero's spell power by %{count}.", "Alongside the remains of a burnt witch lies a beautiful broach, intricately designed. Approaching the corpse with caution, you add the broach to your inventory."),
        new("Medal of Valor", "The %{name} increases the morale of the hero's army by %{count}.", "Freeing a virtuous maiden from the clutches of an evil overlord, you are granted a Medal of Valor by the King's herald."),
        new("Medal of Courage", "The %{name} increases the morale of the hero's army by %{count}.", "After saving a young boy from a vicious pack of Wolves, you return him to his father's manor. The grateful nobleman awards you with a Medal of Courage."),
        new("Medal of Honor", "The %{name} increases the morale of the hero's army by %{count}.", "After freeing a princess of a neighboring kingdom from the evil clutches of despicable slavers, she awards you with a Medal of Honor."),
        new("Medal of Distinction", "The %{name} increases the morale of the hero's army by %{count}.", "Ridding the countryside of the hideous Minotaur who made a sport of eating noblemen's Knights, you are honored with the Medal of Distinction."),
        new("Fizbin of Misfortune", "The %{name} greatly decreases the morale of the hero's army by %{count}.", "You stumble upon a medal lying alongside the empty road. Adding the medal to your inventory, you become aware that you have acquired the undesirable Fizbin of Misfortune, greatly decreasing your army's morale."),
        new("Thunder Mace of Dominion", "The %{name} increases the hero's attack skill by %{count}.", "During a sudden storm, a bolt of lightning strikes a tree, splitting it. Inside the tree you find a mysterious mace."),
        new("Armored Gauntlets of Protection", "The %{name} increase the hero's defense skill by %{count}.", "You encounter the infamous Black Knight! After a grueling duel ending in a draw, the Knight, out of respect, offers you a pair of armored gauntlets."),
        new("Defender Helm of Protection", "The %{name} increases the hero's defense skill by %{count}.", "A glint of golden light catches your eye. Upon further investigation, you find a golden helm hidden under a bush."),
        new("Giant Flail of Dominion", "The %{name} increases the hero's attack skill by %{count}.", "A clumsy Giant has killed himself with his own flail. Knowing your superior skill with this weapon, you confidently remove the spectacular flail from the fallen Giant."),
        new("Ballista of Quickness", "The %{name} gives the hero's catapult one extra shot per combat round.", "Walking through the ruins of an ancient walled city, you find the instrument of the city's destruction, an elaborately crafted ballista."),
        new("Stealth Shield of Protection", "The %{name} increases the hero's defense skill by %{count}.", "A stone statue of a warrior holds a silver shield. As you remove the shield, the statue crumbles into dust."),
        new("Dragon Sword of Dominion", "The %{name} increases the hero's attack skill by %{count}.", "As you are walking along a narrow path, a nearby bush suddenly bursts into flames. Before your eyes the flames become the image of a beautiful woman. She holds out a magnificent sword to you."),
        new("Power Axe of Dominion", "The %{name} increases the hero's attack skill by %{count}.", "You see a silver axe embedded deeply in the ground. After several unsuccessful attempts by your army to remove the axe, you tightly grip the handle of the axe and effortlessly pull it free."),
        new("Divine Breastplate of Protection", "The %{name} increases the hero's defense skill by %{count}.", "A gang of Rogues is sifting through the possessions of dead warriors. Scaring off the scavengers, you note the Rogues had overlooked a beautiful breastplate."),
        new("Minor Scroll of Knowledge", "The %{name} increases the hero's knowledge by %{count}.", "Before you appears a levitating glass case with a scroll, perched upon a bed of crimson velvet. At your touch, the lid opens and the scroll floats into your awaiting hands."),
        new("Major Scroll of Knowledge", "The %{name} increases the hero's knowledge by %{count}.", "Visiting a local wiseman, you explain the intent of your journey. He reaches into a sack and withdraws a yellowed scroll and hands it to you."),
        new("Superior Scroll of Knowledge", "The %{name} increases the hero's knowledge by %{count}.", "You come across the remains of an ancient Druid. Bones, yellowed with age, peer from the ragged folds of her robe. Searching the robe, you discover a scroll hidden in the folds."),
        new("Foremost Scroll of Knowledge", "The %{name} increases the hero's knowledge by %{count}.", "Mangled bones, yellowed with age, peer from the ragged folds of a dead Druid's robe. Searching the robe, you discover a scroll hidden within."),
        new("Endless Sack of Gold", "The %{name} provides the hero with %{count} gold per day.", "A little leprechaun dances gleefully around a magic sack. Seeing you approach, he stops in mid-stride. The little man screams and stamps his foot ferociously, vanishing into thin air. Remembering the old leprechaun saying 'Finders Keepers', you grab the sack and leave."),
        new("Endless Bag of Gold", "The %{name} provides the hero with %{count} gold per day.", "A noblewoman, separated from her traveling companions, asks for your help. After escorting her home, she rewards you with a bag filled with gold."),
        new("Endless Purse of Gold", "The %{name} provides the hero with %{count} gold per day.", "In your travels, you find a leather purse filled with gold that once belonged to a great warrior king who had the ability to transform any inanimate object into gold."),
        new("Nomad Boots of Mobility", "The %{name} increase the hero's movement on land.", "A Nomad trader seeks protection from a tribe of Goblins. For your assistance, he gives you a finely crafted pair of boots made from the softest leather. Looking closely, you see fascinating ancient carvings engraved on the leather."),
        new("Traveler's Boots of Mobility", "The %{name} increase the hero's movement on land.", "Discovering a pair of beautifully beaded boots made from the finest and softest leather, you thank the anonymous donor and add the boots to your inventory."),
        new("Lucky Rabbit's Foot", "The %{name} increases the luck of the hero's army by %{count}.", "A traveling merchant offers you a rabbit's foot, made of gleaming silver fur, for safe passage. The merchant explains the charm will increase your luck in combat."),
        new("Golden Horseshoe", "The %{name} increases the luck of the hero's army by %{count}.", "An ensnared Unicorn whinnies in fright. Murmuring soothing words, you set her free. Snorting and stamping her front hoof once, she gallops off. Looking down you see a golden horseshoe."),
        new("Gambler's Lucky Coin", "The %{name} increases the luck of the hero's army by %{count}.", "You have captured a mischievous imp who has been terrorizing the region. In exchange for his release, he rewards you with a magical coin."),
        new("Four-Leaf Clover", "The %{name} increases the luck of the hero's army by %{count}.", "In the middle of a patch of dead and dry vegetation, to your surprise you find a healthy green four-leaf clover."),
        new("True Compass of Mobility", "The %{name} increases the hero's movement on land and sea.", "An old man claiming to be an inventor asks you to try his latest invention. He then hands you a compass."),
        new("Sailor's Astrolabe of Mobility", "The %{name} increases the hero's movement on sea.", "An old sea captain is being tortured by Ogres. You save him, and in return he rewards you with a wondrous instrument to measure the distance of a star."),
        new("Evil Eye", "The %{name} reduces the casting cost of curse spells by half.", "While venturing into a decrepit hut you find the Skeleton of a long dead witch. Investigation of the remains reveals a glass eye rolling around inside an empty skull."),
        new("Enchanted Hourglass", "The %{name} extends the duration of all the hero's spells by %{count} turns.", "A surprise turn in the landscape finds you in the midst of a grisly scene: Vultures picking at the aftermath of a terrible battle. Your cursory search of the remains turns up an enchanted hourglass."),
        new("Gold Watch", "The %{name} doubles the effectiveness of the hero's hypnotize spells.", "In reward for helping his cart out of a ditch, a traveling potion salesman gives you a \"magic\" gold watch. Unbeknownst to him, the watch really is magical."),
        new("Skullcap", "The %{name} halves the casting cost of all mind influencing spells.", "A brief stop at an improbable rural inn yields an exchange of money, tales, and accidentally, luggage. You find a magical skullcap in your new backpack."),
        new("Ice Cloak", "The %{name} halves all damage the hero's troops receive from cold spells.", "Responding to the panicked cries of a damsel in distress, you discover a young woman fleeing from a hungry bear. You slay the beast in the nick of time, and the grateful Sorceress weaves a magic cloak from the bear's hide."),
        new("Fire Cloak", "The %{name} halves all damage the hero's troops receive from fire spells.", "You've come upon a fight between a Necromancer and a Paladin. The Necromancer blasts the Paladin with a fire bolt, bringing him to his knees. Acting quickly, you slay the evil one before the final blow. The grateful Paladin gives you the fire cloak that saved him."),
        new("Lightning Helm", "The %{name} halves all damage the hero's troops receive from lightning spells.", "A traveling tinker in need of supplies offers you a helm with a thunderbolt design on its top in exchange for food and water. Curious, you accept, and later find out that the helm is magical."),
        new("Evercold Icicle", "The %{name} causes the hero's cold spells to do %{count} percent more damage to enemy troops.", "An icicle withstanding the full heat of the noonday sun attracts your attention. Intrigued, you break it off, and find that it does not melt in your hand."),
        new("Everhot Lava Rock", "The %{name} causes the hero's fire spells to do %{count} percent more damage to enemy troops.", "Your wanderings bring you into contact with a tribe of ape-like beings using a magical lava rock that never cools to light their fires. You take pity on them and teach them to make fire with sticks. Believing you to be a god, the apes give you their rock."),
        new("Lightning Rod", "The %{name} causes the hero's lightning spells to do %{count} percent more damage to enemy troops.", "While waiting out a storm, a lighting bolt strikes a nearby cottage's lightning rod, which melts and falls to the ground. The tip of the rod, however, survives intact and makes your hair stand on end when you touch it. Hmm..."),
        new("Snake-Ring", "The %{name} halves the casting cost of all of the hero's bless spells.", "You've found an oddly shaped ring on the finger of a long dead traveler. The ring looks like a snake biting its own tail."),
        new("Ankh", "The %{name} doubles the effectiveness of all of the hero's resurrect and animate spells.", "A fierce windstorm reveals the entrance to a buried tomb. Your investigation reveals that the tomb has already been looted, but the thieves overlooked an ankh on a silver chain in the dark."),
        new("Book of Elements", "The %{name} doubles the effectiveness of all of the hero's summoning spells.", "You come across a conjurer who begs to accompany you and your army awhile for safety. You agree, and he offers as payment a copy of the book of the elements."),
        new("Elemental Ring", "The %{name} halves the casting cost of all summoning spells.", "While pausing to rest, you notice a bobcat climbing a short tree to get at a crow's nest. On impulse, you climb the tree yourself and scare off the cat. When you look in the nest, you find a collection of shiny stones and a ring."),
        new("Holy Pendant", "The %{name} makes all of the hero's troops immune to curse spells.", "In your wanderings you come across a hermit living in a small, tidy hut. Impressed with your mission, he takes time out from his meditations to bless and give you a charm against curses."),
        new("Pendant of Free Will", "The %{name} makes all of the hero's troops immune to hypnotize spells.", "Responding to cries for help, you find river Sprites making a sport of dunking an old man. Feeling vengeful, you rescue the man and drag a Sprite onto dry land for awhile. The Sprite, uncomfortable in the air, gives you a magic pendant to let him go."),
        new("Pendant of Life", "The %{name} makes all of the hero's troops immune to death spells.", "A brief roadside encounter with a small caravan and a game of knucklebones wins a magic pendant. Its former owner says that it protects from Necromancers' death spells."),
        new("Serenity Pendant", "The %{name} makes all of the hero's troops immune to berserk spells.", "The sounds of combat draw you to the scene of a fight between an old Barbarian and an eight-headed Hydra. Your timely intervention swings the battle in favor of the man, and he rewards you with a pendant he used to use to calm his mind for battle."),
        new("Seeing-eye Pendant", "The %{name} makes all of the hero's troops immune to blindness spells.", "You come upon a very old woman, long blind from cataracts and dying alone. You tend to her final needs and promise a proper burial. Grateful, she gives you a magic pendant emblazoned with a stylized eye. It lets you see with your eyes closed."),
        new("Kinetic Pendant", "The %{name} makes all of the hero's troops immune to paralyze spells.", "You come across a golem wearing a glowing pendant and blocking your way. Acting on a hunch, you cut the pendant from its neck. Deprived of its power source, the golem breaks down, leaving you with the magical pendant."),
        new("Pendant of Death", "The %{name} makes all of the hero's troops immune to holy spells.", "A quick and deadly battle with a Necromancer wins you his magical pendant. Later, a Wizard tells you that the pendant protects undead under your control from holy word spells."),
        new("Wand of Negation", "The %{name} makes all of the hero's troops immune to dispel magic spells.", "You meet an old Wizard friend of yours traveling in the opposite direction. He presents  you with a gift: A wand that prevents the use of the dispel magic spell on your allies."),
        new("Golden Bow", "The %{name} eliminates the %{count} percent penalty for the hero's troops shooting past obstacles (e.g. castle walls).", "A chance meeting with a famous Archer finds you in a game of knucklebones pitting his bow against your horse. You win."),
        new("Telescope", "The %{name} increases the amount of terrain the hero reveals when adventuring by %{count} extra square.", "A merchant from far away lands trades you a new invention of his people for traveling supplies. It makes distant objects appear closer, and he calls it...\n\na telescope."),
        new("Statesman's Quill", "The %{name} reduces the cost of surrender to %{count} percent of the total cost of troops the hero has in their army.", "You pause to help a diplomat with a broken axle fix his problem. In gratitude, he gives you a writing quill with magical properties which he says will \"help people see things your way\"."),
        new("Wizard's Hat", "The %{name} increases the duration of the hero's spells by %{count} turns.", "You see a Wizard fleeing from a Griffin and riding like the wind. The Wizard opens a portal and rides through, getting his hat knocked off by the edge of the gate. The Griffin follows; the gate closes. You pick the hat up, dust it off, and put it on."),
        new("Power Ring", "The %{name} returns %{count} extra spell points per day to the hero.", "You find a small tree that closely resembles the great Warlock Carnauth with a ring around one of its twigs. Scraps of clothing and rotting leather lead you to suspect that it IS Carnauth, transformed. Since you can't help him, you take the magic ring."),
        new("Ammo Cart", "The %{name} provides endless ammunition for all of the hero's troops that shoot.", "An ammunition cart in the middle of an old battlefield catches your eye. Inspection shows it to be in good working order, so  you take it along."),
        new("Tax Lien", "The %{name} costs the hero %{count} gold pieces per day.", "Your big spending habits have earned you a massive tax bill that you can't hope to pay. The tax man takes pity and agrees to only take 250 gold a day from your account for life. Check here if you want one dollar to go to the presidential campaign election fund."),
        new("Hideous Mask", "The %{name} prevents all 'wandering' armies from joining the hero.", "Your looting of the grave of Sinfilas Gardolad, the famous shapeshifting Warlock, unearths his fabled mask. Trembling, you put it on and it twists your visage into an awful grimace! Oh no! It's actually the hideous mask of Gromluck Greene, and you are stuck with it."),
        new("Endless Pouch of Sulfur", "The %{name} provides %{count} unit of sulfur per day.", "You visit an alchemist who, upon seeing your army, is swayed by the righteousness of your cause. The newly loyal subject gives you his endless pouch of sulfur to help with the war effort."),
        new("Endless Vial of Mercury", "The %{name} provides %{count} unit of mercury per day.", "A brief stop at a hastily abandoned Wizard's tower turns up a magical vial of mercury that always has a little left on the bottom. Recognizing a treasure when you see one, you cap it and slip it in your pocket."),
        new("Endless Pouch of Gems", "The %{name} provides %{count} unit of gems per day.", "A short rainstorm brings forth a rainbow...and you can see the end of it. Riding quickly, you seize the pot of gold you find there. The leprechaun who owns it, unable to stop you from taking it, offers an endless pouch of gems for the return of his gold. You accept."),
        new("Endless Cord of Wood", "The %{name} provides %{count} unit of wood per day.", "Pausing to rest and light a cook fire, you pull wood out of a nearby pile of dead wood. As you keep pulling wood from the pile, you notice that it doesn't shrink. You realize to your delight that the wood is enchanted, so you take it along."),
        new("Endless Cart of Ore", "The %{name} provides %{count} unit of ore per day.", "You've found a Goblin weapon smithy making weapons for use against humans. With a tremendous yell you and your army descend upon their camp and drive them away. A search finds a magic ore cart that never runs out of iron."),
        new("Endless Pouch of Crystal", "The %{name} provides %{count} unit of crystal per day.", "Taking shelter from a storm in a small cave, you notice a small patch of crystal in one corner. Curious, you break a piece off and notice that the original crystal grows the lost piece back. You decide to stuff the entire patch into a pouch and take it with you."),
        new("Spiked Helm", "The %{name} increases the hero's attack and defense skills by %{count} each.", "Your army is ambushed by a small tribe of wild (and none too bright) Orcs. You fend them off easily and the survivors flee in all directions. One of the Orcs was wearing a polished spiked helm. Figuring it will make a good souvenir, you take it."),
        new("Spiked Shield", "The %{name} increases the hero's attack and defense skills by %{count} each.", "You come upon a bridge spanning a dry gully. Before you can cross, a Troll steps out from under the bridge and demands payment before it will permit you to pass. You refuse, and the Troll charges, forcing you to slay it. You take its spiked shield as a trophy."),
        new("White Pearl", "The %{name} increases the hero's spell power and knowledge by %{count} each.", "A walk across a dry saltwater lake bed yields an unlikely prize: A white pearl amidst shattered shells and debris."),
        new("Black Pearl", "The %{name} increases the hero's spell power and knowledge by %{count} each.", "Rumors of a Griffin of unusual size preying upon the countryside lead you to its cave lair. A quick, brutal fight dispatches the beast, and a search of its foul nest turns up a huge black pearl."),
        new("Magic Book", "The %{name} enables the hero to cast spells.", null),
        new("Ultimate Artifact", "Victory can be achieved by finding any Ultimate Artifact.", null),
        new("Dummy 2", "The reserved artifact.", null),
        new("Dummy 3", "The reserved artifact.", null),
        new("Dummy 4", "The reserved artifact.", null),
        new("Spell Scroll", "This %{name} gives the hero the ability to cast the %{spell} spell if the hero has a Magic Book.", "You find an elaborate container which houses an old vellum scroll. The runes on the container are very old, and the artistry with which it was put together is stunning. As you pull the scroll out, you feel imbued with magical power."),
        new("Arm of the Martyr", "The %{name} increases the hero's spell power by %{count} but adds the undead morale penalty.", "One of the less intelligent members of your party picks up an arm off of the ground. Despite its missing a body, it is still moving. Your troops find the dismembered arm repulsive, but you cannot bring yourself to drop it: it seems to hold some sort of magical power that influences your decision making."),
        new("Breastplate of Anduran", "The %{name} increases the hero's defense by %{count}.", "You come upon a sign. It reads: \"Here lies the body of Anduran. Bow and swear fealty, and you shall be rewarded.\" You decide to do as it says. As you stand up, you feel a coldness against your skin. Looking down, you find that you are suddenly wearing a gleaming, ornate breastplate."),
        new("Broach of Shielding", "The %{name} provides %{count} percent protection from Armageddon and Elemental Storm, but decreases spell power by 2.", "A kindly Sorceress thinks that your army's defenses could use a magical boost. She offers to enchant the Broach that you wear on your cloak, and you accept."),
        new("Battle Garb of Anduran", "The %{name} combines the powers of the three Anduran artifacts (+5 to attack, defense, and spell power). It also provides maximum luck and morale for the hero's troops and gives the hero the Town Portal spell.", "Out of pity for a poor peasant, you purchase a chest of old junk they are hawking for too much gold. Later, as you search through it, you find it contains the 3 pieces of the legendary battle garb of Anduran!"),
        new("Crystal Ball", "The %{name} lets the hero get more specific information about monsters, enemy heroes, and castles nearby the hero.", "You come upon a caravan of gypsies who are feasting and fortifying their bodies with mead. They call you forward and say \"If you prove that you can dance the Rama-Buta, we will reward you.\" You don't know it, but try anyway. They laugh hysterically, but admire your bravery, giving you a Crystal Ball."),
        new("Heart of Fire", "The %{name} provides %{count} percent protection from fire, but doubles the damage taken from cold.", "You enter a recently burned glade and come upon a Fire Elemental sitting atop a rock. It looks up, its flaming face contorted in a look of severe pain. It then tosses a glowing object at you. You put up your hands to block it, but it passes right through them and sears itself into your chest."),
        new("Heart of Ice", "The %{name} provides %{count} percent protection from cold, but doubles the damage taken from fire.", "Suddenly, a biting coldness engulfs your body. You seize up, falling from your horse. The pain subsides, but you still feel as if your chest is frozen. As you pick yourself up off of the ground, you hear hearty laughter. You turn around just in time to see a Frost Giant run off into the woods and disappear."),
        new("Helmet of Anduran", "The %{name} increases the hero's spell power by %{count}.", "You spy a gleaming object poking up out of the ground. You send a member of your party over to investigate. He comes back with a golden helmet in his hands. You realize that it must be the helmet of the legendary Anduran, the only man who was known to wear solid gold armor."),
        new("Holy Hammer", "The %{name} increases the hero's attack skill by %{count}.", "You come upon a battle where a Paladin has been mortally wounded by a group of Zombies. He asks you to take his hammer and finish what he started. As you pick it up, it begins to hum, and then everything becomes a blur. The Zombies lie dead, the hammer dripping with blood. You strap it to your belt."),
        new("Legendary Scepter", "The %{name} adds %{count} points to all attributes.", null),
        new("Masthead", "The %{name} boosts the hero's troops' luck and morale by %{count} each in sea combat.", "An old seaman tells you a tale of an enchanted masthead that he used in his youth to rally his crew during times of trouble. He then hands you a faded map that shows where he hid it. After much exploring, you find it stashed underneath a nearby dock."),
        new("Sphere of Negation", "The %{name} disables all spell casting, for both sides, in combat.", "You stop to help a Peasant catch a runaway mare. To show his gratitude, he hands you a tiny sphere. As soon as you grasp it, you feel the magical energy drain from your limbs..."),
        new("Staff of Wizardry", "The %{name} boosts the hero's spell power by %{count}.", "While out scaring up game, your troops find a mysterious staff levitating about three feet off of the ground. They hand it to you, and you notice an inscription. It reads: \"Brains best brawn and magic beats might. Heed my words, and you'll win every fight.\""),
        new("Sword Breaker", "The %{name} increases the hero's defense by %{count} and attack by 1.", "A former Captain of the Guard admires your quest and gives you the enchanted Sword Breaker that he relied on during his tour of duty."),
